"""Constructor-based circle packing for n=26 circles (hexagonal brick)."""
import numpy as np

N = 26


def _solve_radii(centers):
    """Feasible radii via wall-limit then sequential pair-scaling."""
    n = centers.shape[0]
    radii = np.empty(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                if radii[i] + radii[j] > dist:
                    scale = dist / (radii[i] + radii[j])
                    radii[i] *= scale
                    radii[j] *= scale
                    changed = True
        if not changed:
            break
    return radii


def _brick(s, vs):
    xs6 = 0.5 + (np.arange(6) - 2.5) * s
    xs5 = 0.5 + (np.arange(5) - 2.0) * s
    ys = np.linspace(0.5 - 2 * vs, 0.5 + 2 * vs, 5)
    centers = []
    for ri, y in enumerate(ys):
        xs = xs6 if ri == 2 else xs5
        centers.extend([(x, y) for x in xs])
    return np.array(centers, dtype=float)


def construct_packing():
    best_c = None
    best_s = -1.0
    for s in np.linspace(0.16, 0.21, 6):
        for vs in np.linspace(0.16, 0.21, 6):
            c = _brick(s, vs)
            # require strict interior
            if c[:, 0].min() < 1e-4 or c[:, 0].max() > 1 - 1e-4:
                continue
            if c[:, 1].min() < 1e-4 or c[:, 1].max() > 1 - 1e-4:
                continue
            r = _solve_radii(c)
            ssum = float(np.sum(r))
            if ssum > best_s:
                best_s = ssum
                best_c = c
    radii = _solve_radii(best_c)
    return best_c, radii, float(np.sum(radii))
# EVOLVE-BLOCK-END

